import heapq

def earliestSecondToMarkIndices(nums, changeIndices):
    n, m = len(nums), len(changeIndices)
    if n > m:
        return -1
    total = sum(nums)

    def check(t):
        # first occurrence (0-based second) of each index within the first t seconds
        first = [-1] * n
        for s in range(t - 1, -1, -1):
            first[changeIndices[s] - 1] = s

        heap = []   # values of indices that are zeroed with a "set" operation
        free = 0    # seconds seen so far (to the right) not yet pledged to a mark
        for s in range(t - 1, -1, -1):
            i = changeIndices[s] - 1
            v = nums[i]
            if v <= 1 or s != first[i]:
                free += 1                      # free second (decrement or mark)
            elif free > 0:
                heapq.heappush(heap, v)        # use this second to set nums[i] = 0
                free -= 1                      # pledge one later second for its mark
            elif heap and heap[0] < v:
                heapq.heapreplace(heap, v)     # regret: prefer the larger value
                free += 1
            else:
                free += 1

        slots = t - len(heap)                  # seconds not used by "set"
        need = n + total - sum(heap)           # marks + remaining decrements
        return slots >= need

    if not check(m):
        return -1
    lo, hi = n, m
    while lo < hi:
        mid = (lo + hi) // 2
        if check(mid):
            hi = mid
        else:
            lo = mid + 1
    return lo
